export function genererRestitutionPdf(
  fruitConfig: any,
  resultatCalcul: any,
  user: { prenom: string; nom: string; email: string; eglise?: string },
  logoPrincipal?: string
): { blob: Blob; nomFichier: string } {
  LOGO = logoPrincipal ?? LOGO_CHRISTOSMETRICS;
  fruit = fruitConfig;
  resultat = resultatCalcul;
  identite = { prenom: user.prenom, nom: user.nom, mail: user.email, eglise: user.eglise ?? '' };

  let blob: Blob | null = null;
  let nomFichier = 'restitution.pdf';

  const patch = (doc: any) => {
    doc.telecharger = (nom: string) => {
      nomFichier = nom;
      blob = new Blob([doc.construire()], { type: 'application/pdf' });
    };
    return doc;
  };
  const creerOrig = (MiniPDF as any).creer;
  (MiniPDF as any).creer = () => patch(creerOrig());
  try {
    (globalThis as any).genererPDF();
  } finally {
    (MiniPDF as any).creer = creerOrig;
  }
  if (!blob) throw new Error('PDF non produit');
  return { blob, nomFichier };
}

(globalThis as any).genererPDF = genererPDF;
(globalThis as any).dessinerRadar = dessinerRadar;
(globalThis as any).dessinerEntonnoir = dessinerEntonnoir;
(globalThis as any).dessinerDeuxBarres = dessinerDeuxBarres;
(globalThis as any).dessinerVisagesPDF = dessinerVisagesPDF;
(globalThis as any).dateRestitution = dateRestitution;
